import{_ as t,o as n,c as a,ak as r}from"./chunks/framework.B8jO0odJ.js";const u=JSON.parse('{"title":"Chainy technical acceptance","description":"Game design · Product acceptance · Technical design","frontmatter":{"title":"Chainy technical acceptance","description":"Game design · Product acceptance · Technical design","source":"docs/requirements/technical-requirements.md","category":"Requirements","sourceUpdated":"2026-11-11T12:24:37+08:00","outline":[2,3]},"headers":[],"relativePath":"content/docs/requirements/technical-requirements.md","filePath":"content/docs/requirements/technical-requirements.md"}'),i={name:"content/docs/requirements/technical-requirements.md"};function s(c,e,o,d,l,p){return n(),a("div",null,[...e[0]||(e[0]=[r('<div><h1 id="chainy-technical-acceptance">Chainy technical acceptance<a class="header-anchor" href="#chainy-technical-acceptance" aria-label="Link to this section">​</a></h1><p><a href="/Chainy-Docs/content/docs/game-design-lesson-collection.html">Game design</a> · <a href="/Chainy-Docs/content/docs/requirements/product-requirements.html">Product acceptance</a> · <a href="/Chainy-Docs/content/docs/technical-design.html">Technical design</a></p><p><strong>Documentation and preparation only until the owner&#39;s explicit FINAL approval.</strong> These are planned acceptance checks, not a passing implementation report. Christian owns technical integration; Sean records the evidence and Miguel owns UI implementation.</p><h2 id="required-checks-after-approval">Required checks after approval<a class="header-anchor" href="#required-checks-after-approval" aria-label="Link to this section">​</a></h2><table><thead><tr><th>Area</th><th>Acceptance behavior</th></tr></thead><tbody><tr><td>Build and device</td><td>Identify revision, Unity version, SQLite binding, Android settings, and APK; retain API 25 minimum installation and Android 10/API 29 reference testing</td></tr><tr><td>Offline boundary</td><td>All gameplay and local saving work without network access; AI is a labeled teaching simulation</td></tr><tr><td>Architecture</td><td>Reuse existing views, handlers, services, typed notifications, and database owner; no scene/UI code writes SQL or grants progress directly</td></tr><tr><td>Content</td><td>Exactly 39 stable lesson IDs, 13 per world; nine distinct activities; 13 fixed questions per world with one question mapped to every lesson</td></tr><tr><td>World access</td><td>Only Web3 starts unlocked; saved Web3 completion unlocks Blockchain, then saved Blockchain completion unlocks AI</td></tr><tr><td>Tutorial/order</td><td>Tutorial completion is per profile/world; only the current lesson advances; future objects stay available and recorded objects cannot double count</td></tr><tr><td>Prerequisites</td><td>Item then NPC steps save before facility launch; future steps are rejected; exit/restart retains completed steps</td></tr><tr><td>Activity lifecycle</td><td>One launch at a time; Retry stays in its scene; Exit returns to its originating island without completion; success satisfies its own GDD rule</td></tr><tr><td>Lesson transaction</td><td>Lesson, encyclopedia entry, next objective, collection status, and prerequisite reset commit together before the UI advances</td></tr><tr><td>Review correction</td><td>All 13 questions are required; wrong answers retain the current question with feedback until correct; first responses remain unchanged by retries</td></tr><tr><td>Attempt history</td><td>Each review has its own identity; incomplete attempts are abandoned and return restarts all 13; replay cannot revoke earlier completion</td></tr><tr><td>Completion/unlock</td><td>All 13 entries plus 13 correctly resolved review items are required; Finish-save failure keeps new access locked and offers Retry Save</td></tr><tr><td>Save safety</td><td>Duplicate/racing requests cannot duplicate progress or first responses; failed saves preserve the prior checkpoint and pending retry meaning</td></tr><tr><td>Profile/relaunch</td><td>Two synthetic profiles remain separate; stale callbacks are rejected; committed checkpoints survive app close and interrupted return loading</td></tr><tr><td>Versions/update</td><td>Unknown or damaged records are preserved with recovery feedback; explicit compatibility and in-place update tests precede migration acceptance</td></tr><tr><td>Input/accessibility</td><td>Overlays, pending saves, and backgrounding prevent unintended input; text, touch targets, color-independent feedback, and muted use work on the reference phone</td></tr><tr><td>Performance</td><td>Measure representative exploration, all activities, loading, and saving on the reference phone; editor results do not establish mobile performance</td></tr></tbody></table><p>A completed review shows first responses as X/13 separately from completion after corrections. A partial abandoned attempt is not reported as a finished score. Collection and corrected completion do not establish mastery, learning gain, or school grading.</p><h2 id="evidence-standard-and-current-limits">Evidence standard and current limits<a class="header-anchor" href="#evidence-standard-and-current-limits" aria-label="Link to this section">​</a></h2><p>Each later report names the source revision/build, non-sensitive device specification, steps, expected result, actual result, and evidence location. Use synthetic profiles and fictional lesson data for technical checks. Keep identities, credentials, and signing keys out of repository evidence.</p><p>The <a href="/Chainy-Docs/content/docs/project-baseline.html#current-implementation-evidence">November 11 baseline</a> records existing systems and 57 passing legacy Wordle EditMode tests. It does not establish this checklist&#39;s new gameplay or Android acceptance. Android Build Support was missing and the attempted installation was cancelled; readiness remains unverified. See <a href="/Chainy-Docs/content/docs/hardware-validation.html">device validation</a>, <a href="/Chainy-Docs/content/docs/design/database-schema.html">data invariants</a>, and <a href="/Chainy-Docs/content/docs/offline-data-plan.html">offline record meanings</a>.</p><p>No economy balances, teacher enrollment, vouchers, dashboards, export/transfer services, standalone Wordle, or BlockMatch are current acceptance requirements. The <a href="/Chainy-Docs/content/docs/archive/pre-lesson-collection-2026-11-11/requirements/technical-requirements.html">previous checklist</a> preserves earlier proposals and scope notes. No code, schema change, scene edit, test execution, or build is authorized by this document. <strong>Pre-final remains November 21, 2026</strong>, with integration, device QA, manuscript evidence, and rehearsal still required.</p></div>',1)])])}const m=t(i,[["render",s]]);export{u as __pageData,m as default};
